(() => {
  // st-hde capture helper: a car set down behind the player, the film loop stepped frame by frame, and the closest the
  // car comes to the player, the streetcars, the people on foot and the other traffic logged at each phase
  const app = window.__CITY_APP, T = app.trafficSystem, N = T.network;
  const movers = {};
  const setObstacles = T.setObstacles;
  T.setObstacles = (list, src = 'streetcars') => { movers[src] = list || []; return setObstacles(list, src); };
  const box = (x, z, yaw, halfL, halfW) => ({ x, z, tx: Math.sin(yaw), tz: Math.cos(yaw), halfL, halfW });
  const sep = (a, b) => {
    const dx = b.x - a.x, dz = b.z - a.z;
    const along = Math.abs(b.tx * a.tx + b.tz * a.tz), across = Math.abs(b.tx * a.tz - b.tz * a.tx);
    return Math.max(
      Math.abs(dx * a.tx + dz * a.tz) - a.halfL - b.halfL * along - b.halfW * across,
      Math.abs(dx * a.tz - dz * a.tx) - a.halfW - b.halfL * across - b.halfW * along,
      Math.abs(dx * b.tx + dz * b.tz) - b.halfL - a.halfL * along - a.halfW * across,
      Math.abs(dx * b.tz - dz * b.tx) - b.halfW - a.halfL * across - a.halfW * along);
  };
  const DIMS = { person: [0.32, 0.32], cyclist: [0.85, 0.35], car: [2.18, 0.86] };
  const S = window.__swerve = { car: null, edge: null, lane: 0, frames: 0 };
  const playerBox = () => {
    const mode = app.controllerManager.activeMode, p = app.controllerManager.getActiveEntity(), [L, W] = DIMS[mode] || DIMS.person;
    return box(p.position.x, p.position.z, p.heading || 0, L, W);
  };
  S.track = () => {
    const c = S.car;
    if (!c || !c.edge) return;
    const b = box(c.x, c.z, c.yaw + c.yawOffset, c.half, c.halfWidth), m = S.min;
    m.player = Math.min(m.player, sep(b, playerBox()));
    for (const list of Object.values(movers)) for (const o of list) {
      if (Math.abs(o.x - c.x) < 40 && Math.abs(o.z - c.z) < 40) m.streetcars = Math.min(m.streetcars, sep(b, box(o.x, o.z, o.yaw, o.halfL, o.halfW)));
    }
    for (const p of T.peds) if (p.placed && Math.abs(p.x - c.x) < 12 && Math.abs(p.z - c.z) < 12) m.peds = Math.min(m.peds, sep(b, box(p.x, p.z, 0, 0.3, 0.3)));
    for (const o of [...T.cars, ...T.buses]) {
      if (o !== c && o.edge && Math.abs(o.x - c.x) < 15 && Math.abs(o.z - c.z) < 15 && Math.abs((o.y || 0) - (c.y || 0)) < 2.5) {
        m.others = Math.min(m.others, sep(b, box(o.x, o.z, o.yaw + o.yawOffset, o.half, o.halfWidth)));
      }
    }
    m.dlMin = Math.min(m.dlMin, c.dl);
    m.dlMax = Math.max(m.dlMax, c.dl);
    if (c.dodge) m.dodges[c.dodge] = (m.dodges[c.dodge] || 0) + 1;
    m.steerMax = Math.max(m.steerMax, Math.abs(c.steer));
  };
  S.step = async (n = 1) => {
    for (let i = 0; i < n; i++) { await app.film.step(1); S.frames++; S.track(); }
  };
  S.until = async (cond, max = 900) => {
    let n = 0;
    while (n < max && !cond(S.car)) { await S.step(1); n++; }
    return n;
  };
  // across the road at the player: where the roadway is clear (isRoadClear), right of the centre line
  const roadway = (e, s) => {
    let lo = null, hi = null;
    for (let o = -12; o <= 12; o += 0.25) {
      const x = e.sx + e.dx * s + e.rx * o, z = e.sz + e.dz * s + e.rz * o;
      if (N.isRoadClear(x, z, 0.05)) { if (lo === null) lo = o; hi = o; }
    }
    return [lo, hi];
  };
  S.log = (phase) => {
    const c = S.car, e = S.edge;
    const r = (v) => (Number.isFinite(v) ? Math.round(v * 100) / 100 : v);
    console.log('[ride-check] swerve ' + JSON.stringify({ phase, frames: S.frames, t: r(S.frames / 30),
      car: c && { speed: r(c.speed), dl: r(c.dl), evade: r(c.evade), dodge: c.dodge, panic: c.panicUntil > 0, steerDeg: r(c.steer * 180 / Math.PI),
        noseDeg: r(c.nose * 180 / Math.PI), blink: c.blink, pAhead: r(c.pAhead), pRight: r(c.pRight), onEdge: c.edge === e, lane: c.lane },
      min: Object.fromEntries(Object.entries(S.min).map(([k, v]) => [k, typeof v === 'number' ? r(v) : v])),
      streetcarsNear: Object.values(movers).flat().filter((o) => c && Math.hypot(o.x - c.x, o.z - c.z) < 60).length }));
  };
  // A street near (X, Z): 'side', one lane each way and no tracks; 'king', two lanes or more with a streetcar's
  // tracks. The player (already in its mode) stands in the first lane (curb: the last) lead m ahead of where the car is
  // set down, at speed (default: its pace).
  // (walk: the player starts that far right of the lane's centre, on the curb, and walks across at that input)
  S.setup = async ({ name, kind, X, Z, lat, lon, lead = 45, speed = null, curb = false, skip = 0, walk = null }) => {
    app.controllerManager.setGamepadInput('forward', 0);
    if (lat !== undefined) ({ x: X, z: Z } = window.CITY.worldFromLatLon(lat, lon));
    if (!app.film.active) app.film.start(30);
    if (!S.hudHidden) { document.getElementById('btn-toggle-hud')?.click?.(); S.hudHidden = true; }
    const ok = (e) => e.len > lead + (kind === 'king' ? 45 : 80) && !((e.h0 || 0) > 0.5 || (e.h1 || 0) > 0.5) && !e.busOnly &&
      (kind === 'king' ? e.tram && Math.abs(e.dx) > 0.9 : !e.tram && e.lanes.length === 1 && e.opposite && e.opposite.lanes.length === 1 && e.axis !== 'ave');
    // (King: the street's centre line at that spot, as tools/shots/streetcars.json finds it)
    if (kind === 'king') {
      const n = (window.CITY.nearestRoads(X, Z, 120) || []).find((r) => /^King Street/.test(r.road && r.road.name));
      if (n) { X = n.px; Z = n.pz; }
    }
    const mid = (e) => Math.hypot(e.sx + e.dx * e.len / 2 - X, e.sz + e.dz * e.len / 2 - Z);
    // (on King, two lanes or more first: a curb lane beside the track)
    const key = (e) => mid(e) + (kind === 'king' && e.lanes.length < 2 ? 300 : 0);
    const list = N.edges.filter(ok).sort((a, b) => key(a) - key(b));
    if (kind === 'king') console.log('[ride-check] swerve-king-near ' + JSON.stringify(N.edges.filter((e) => e.tram && mid(e) < 160)
      .map((e) => ({ m: Math.round(mid(e)), len: Math.round(e.len), lanes: e.lanes, dx: +e.dx.toFixed(2) }))));
    const e = list[skip] || list[0];
    if (!e) throw new Error('no ' + kind + ' street near ' + Math.round(X) + ', ' + Math.round(Z));
    const lane = curb ? e.lanes.length - 1 : 0;
    const s0 = 18, ps = s0 + lead;
    const at = (s, l) => [e.sx + e.dx * s + e.rx * e.lanes[l], e.sz + e.dz * s + e.rz * e.lanes[l]];
    let [px, pz] = at(ps, lane);
    if (walk) { px += e.rx * walk.offset; pz += e.rz * walk.offset; }
    app.teleportTo(px, pz, walk ? Math.atan2(-e.rx, -e.rz) : Math.atan2(e.dx, e.dz));
    await S.step(2);
    // a car from the far side of the pool (or not on the streets) set down behind
    const p = app.controllerManager.getActiveEntity().position;
    const c = T.cars.filter((v) => !v.isPolice && (!v.edge || Math.hypot(v.x - p.x, v.z - p.z) > 250))[0];
    T.placeVehicle(c, e, lane, s0);
    c.speed = speed ?? c.v0 * 0.9;
    Object.assign(S, { car: c, edge: e, lane, frames: 0,
      min: { player: Infinity, streetcars: Infinity, peds: Infinity, others: Infinity, dlMin: 0, dlMax: 0, dodges: {}, steerMax: 0 } });
    // the camera behind and above the car, a little to its left, looking on past it
    app.cameraSystem.cinema = () => {
      const lx = e.dz, lz = -e.dx;
      return { pos: [c.x - e.dx * 11 + lx * 3, (c.y || 0) + 3.6, c.z - e.dz * 11 + lz * 3],
        look: [c.x + e.dx * 14, (c.y || 0) + 0.6, c.z + e.dz * 14], fov: 58 };
    };
    if (walk) app.controllerManager.setGamepadInput('forward', walk.input);
    await S.step(1);
    const [lo, hi] = roadway(e, ps);
    const road = (window.CITY.nearestRoads?.(px, pz, 30) || [])[0];
    console.log('[ride-check] swerve-setup ' + JSON.stringify({ name, kind, street: road && road.road && road.road.name, edge: { x: Math.round(e.sx + e.dx * ps), z: Math.round(e.sz + e.dz * ps),
      dir: [+e.dx.toFixed(3), +e.dz.toFixed(3)], lanes: e.lanes, half: e.half, len: Math.round(e.len), tram: !!e.tram, opposite: !!e.opposite,
      divided: !!e.divided, clearAcross: [lo, hi] }, lane, player: { x: +p.x.toFixed(2), z: +p.z.toFixed(2), mode: app.controllerManager.activeMode },
      car: { kind: c.bodyType, v0: +c.v0.toFixed(1), speed: +c.speed.toFixed(1) }, candidates: list.length }));
  };
  console.log('[ride-check] swerve helper ready');
})()
